//! Cargo-driven `framedyn.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x74f50000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff1f000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff1f000000u64)),
        o => panic!("framedyn-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:c:cpprt", "import:oleaut32", "import:msvcrt", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "body", "engine:oldnames", "import:kernel32_vista"],
        "x86_64" => &["engine:c:cpprt", "import:oleaut32", "import:msvcrt", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "body", "engine:oldnames", "import:kernel32_vista"],
        "aarch64" => &["engine:c:cpprt", "import:oleaut32", "import:msvcrt", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "body", "engine:oldnames", "import:kernel32_vista"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .c_from_compile_db("framedyn_shims", &["dll/win32/framedyn/main.c", "dll/win32/framedyn/chstring.cpp", "dll/win32/framedyn/provider.cpp"])
        .spec2def("dll/win32/framedyn/framedyn.spec", "framedyn.dll")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
